/// Count how many participants in `participations` are eligible given `k`,
/// using the rule: eligible iff 5 - attendance >= k.
pub fn count_eligible(participations: &[u8], k: u8) -> usize {
    // Avoid u8 underflow if k > 5 by clamping the threshold.
    // Eligible iff attendance <= 5 - k, but only meaningful for k <= 5.
    let threshold: i16 = 5 - (k as i16);

    participations
        .iter()
        .filter(|&&a| (a as i16) <= threshold)
        .count()
}

/// Compute maximum number of teams of exactly three eligible participants.
/// Only the first min(n, participations.len()) elements are considered.
pub fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let take_n = (n as usize).min(participations.len());
    let eligible = count_eligible(&participations[..take_n], k);
    let teams = eligible / 3;
    teams as u8
}

